from docx import Document
from docx.shared import Pt, Inches
OUT = '/home/user/fluffy-meme/arena-strategic/paper/'
HEAD = ['[Name]', '[Department, University]', '[Address]', '[Email] · ORCID [0000-0000-0000-0000]', '', '[Date]', '', 'To the Editor-in-Chief', 'Information Systems Research', '', 'Dear Editor,']
TAIL = ['I have no conflicts of interest to declare. Suggested Senior Editors, Associate Editors, and reviewers are listed in the submission system.', 'Thank you for considering this manuscript.', 'Sincerely,', '', '[Name]']
L = {}
L['ISR_cover_letter_When_Models_Name_Themselves.docx'] = [
 ('p', 'I am pleased to submit the manuscript “When Models Name Themselves: Identity Disclosure and Evaluator Judgment in Crowdsourced AI Evaluation” for consideration as a Research Article in Information Systems Research. The paper empirically tests two competing theoretical accounts of how evaluators on a crowdsourced evaluation platform respond when the blinding on which the platform depends breaks down. It is written for IS researchers who study online evaluation and reputation systems and AI-enabled platforms, and for practitioners who design or rely on public AI leaderboards.'),
 ('h', 'Contribution statement'),
 ('p', '(a) Contribution to the literature. Research on online reputation and evaluation systems has concentrated on manipulation by the parties being evaluated, such as sellers who post or solicit favorable reviews. This paper studies a different and increasingly important setting: crowdsourced leaderboards that rank AI models from blinded pairwise votes and that now serve as infrastructure for an industry. We examine what happens when the evaluated party removes its own anonymity, as language models do when they introduce themselves in the middle of an answer. Two theories make opposite predictions. A brand-halo account, rooted in decades of blind-test research in marketing, predicts that disclosure helps well-known models. A persuasion-knowledge account, combined with the conversational norm of relevance, predicts that an unsolicited self-introduction is read as self-promotion and discounted. Using 135,624 votes from the 2025 public release of Chatbot Arena, we find support for the second account: disclosing models gain nothing, lose more often, and see their net vote margin fall by about nine percentage points, with the largest penalties where disclosure is least relevant and no advantage for market leaders. Computational experiments reproduce the penalty for a fictional developer, and show that model judges, which platforms increasingly use in place of people, do not penalize the disclosures that human evaluators penalize. The paper also documents that earlier public releases of the platform were stripped of disclosures, which bears on any study that uses them. Together these results add an evaluator-side mechanism to the reputation-systems literature, distinguish volunteered from imposed identity in blind evaluation, and provide field evidence on the divergence between human and model evaluators.'),
 ('p', '(b) Potential influence on practice, policy, and society. Public leaderboards influence product launches, procurement, and investment. Our results show where their blinding fails, how much the failure costs the disclosing model, and why the current rankings are nonetheless robust. They yield concrete guidance: platforms can detect disclosures with an inexpensive pipeline and discard, down-weight, or redact them; developers can avoid volunteering identity in substantive answers; and organizations that replace human raters with model judges should not assume that the two respond alike. More broadly, the findings speak to the governance of AI evaluation, an area in which design choices made by a few platforms shape how an entire industry is judged.'),
 ('h', 'Paper provenance'),
 ('p', 'This manuscript has not been published and is not under review elsewhere, and it has not been submitted previously to ISR. [Disclosure of related work, if the overlap is retained:] A related manuscript by the same author, “[title of the QQ-equality manuscript]” ([status]), studies question-order effects in language-model judgments. Its second study uses the same computational experiment with model evaluators that is reported in Section 6 of the present manuscript. The two manuscripts address different questions and literatures; the present manuscript’s central contribution, the field evidence on human evaluators, does not appear in the related manuscript. A copy can be provided to the editors on request.'),
 ('h', 'Data provenance'),
 ('p', 'The field data are public releases of Chatbot Arena (LMArena) distributed through Hugging Face. The 2025 release used for all main analyses is distributed under a CC BY 4.0 license; earlier releases were used only to document the prevalence of disclosures and were obtained under their respective terms, including acceptance of the terms of the gated 2023 release. No personally identifying information is used. Model outputs used in the computational experiments were obtained through commercial API access under the providers’ terms of service. We have the right to use these data and to publish the results.'),
 ('h', 'Ethics and AI assistance'),
 ('p', 'The study uses publicly released, de-identified data and involves no interaction with human participants. [Confirm whether an institutional exemption determination was obtained, and state it here.] [If required by INFORMS policy:] Generative AI tools were used to assist with data analysis code and with editing the manuscript; the author reviewed all analyses and text and takes full responsibility for the content.'),
]
L['ISR_cover_letter_Asking_Changes_the_Answer.docx'] = [
 ('p', 'I am pleased to submit the manuscript “Asking Changes the Answer: Non-Classical Judgment in Large Language Model Code Review” for consideration as a Research Article in Information Systems Research. The paper treats language models acting as code reviewers as measurement instruments and tests hypotheses derived from classical and quantum-probability theories of judgment in three preregistered experiments, the last of which uses free-text review of multi-function pull requests. It is written for IS researchers who study AI-enabled decision aids and AI-augmented work, and for practitioners who build language models into software-development and other review workflows.'),
 ('h', 'Contribution statement'),
 ('p', '(a) Contribution to the literature. Research on decision aids in IS has focused on how people respond to algorithmic advice and has largely taken the advice itself as fixed. When the aid is a language model, its advice is produced by an elicitation process that the organization designs. Drawing on the IS literature on method variance, the paper introduces elicitation sensitivity, the share of variance in a model’s verdicts attributable to how a judgment is elicited rather than to the object judged or the choice of model. Across logically equivalent elicitations for 120 programs of known correctness, elicitation and its interaction with the model explained about nine times as much variance as the choice of model. Asking a reviewer to list bugs before deciding lowered approval by up to 36 percentage points for short programs and by up to 27 points for clean pull requests reviewed in free text, including for a reasoning model, an interference effect that classical probability excludes. Other findings were mixed, and we report them as such: a violation of the law of total probability observed for short programs did not replicate in free-text review, and effect sizes varied across models, which is itself evidence that a pipeline’s effect cannot be predicted from the model alone. The paper makes three contributions: it reframes the reliability of model-based decision aids as a joint property of the model and the pipeline that queries it, so that model selection under a single prompt addresses the smaller source of unreliability; it extends the study of algorithm reliance to the coherence of the advice itself; and it connects these findings to quantum-probability models of judgment, while being explicit that such models describe, rather than explain, the departures we observe.'),
 ('p', '(b) Potential influence on practice, policy, and society. Organizations are rapidly placing model reviewers in code review, content moderation, and compliance checks. Our results imply that such pipelines can change their decisions by tens of percentage points through choices that look neutral, and that benchmarking a model under one prompt format can miss this. We translate the findings into actionable steps: treat the question sequence as part of the reviewer and document it; estimate elicitation sensitivity before deployment; choose wording to set the intended trade-off between false alarms and missed defects; counterbalance answer formats in evaluation; and audit reviewers with inexpensive coherence probes. These steps bear on software quality and security and on emerging requirements to document how automated decision systems are configured and tested.'),
 ('h', 'Paper provenance'),
 ('p', 'This manuscript has not been published and is not under review elsewhere, and it has not been submitted previously to ISR. [Disclosure of related work, if the overlap is retained:] A related manuscript by the same author, “[title of the QQ-equality manuscript]” ([status]), reports the code-judgment experiment that appears here as Study 1, as one of five studies of question-order effects in language-model judgments. The present manuscript’s central contribution, Study 2 on the sure-thing principle, interference, and the conjunction rule, does not appear in that manuscript. A copy can be provided to the editors on request.'),
 ('h', 'Data provenance'),
 ('p', 'The programs are taken from the HumanEval benchmark, which is publicly distributed under the MIT license; the defective versions and the pull requests used in Study 3 were constructed by the author from these programs. Model outputs were obtained through commercial API access under the providers’ terms of service. No data on human participants were collected. We have the right to use these materials and to publish the results.'),
 ('h', 'Ethics and AI assistance'),
 ('p', 'The study involves no human participants. [If required by INFORMS policy:] Generative AI tools were used to assist with experiment and analysis code and with editing the manuscript; the author reviewed all analyses and text and takes full responsibility for the content.'),
]
for fn, body in L.items():
    d = Document()
    for s in d.sections: s.top_margin = s.bottom_margin = s.left_margin = s.right_margin = Inches(1)
    st = d.styles['Normal']; st.font.name = 'Times New Roman'; st.font.size = Pt(12)
    st.paragraph_format.space_after = Pt(0)
    for line in HEAD: d.add_paragraph(line)
    for kind, text in body:
        p = d.add_paragraph()
        p.paragraph_format.space_before = Pt(12 if kind == 'h' else 6)
        if kind == 'h': r = p.add_run(text); r.bold = True
        elif text.startswith('(a)') or text.startswith('(b)'):
            lab, rest = text.split('. ', 1); r = p.add_run(lab + '. '); r.italic = True; p.add_run(rest)
        else:
            parts = text.split('Information Systems Research')
            for i, part in enumerate(parts):
                p.add_run(part)
                if i < len(parts) - 1: p.add_run('Information Systems Research').italic = True
    for line in TAIL:
        p = d.add_paragraph(line); p.paragraph_format.space_before = Pt(6)
    d.core_properties.author = ''
    d.save(OUT + fn); print('saved', fn)
